        "agents.<name>.config_file": .init(en: "Path to a TOML config layer for that role; relative paths resolve from the config file that declares the role.", es: "Ruta a una capa de configuración TOML para ese rol; las rutas relativas se resuelven desde el archivo de configuración que declara el rol.", spec: .init(
            kind: .string, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "agents", deprecated: false, min: nil, max: nil)),
        "agents.<name>.description": .init(en: "Role guidance shown to Codex when choosing and spawning that agent type.", es: "Guía del rol que se muestra a Codex al elegir y generar ese tipo de agente.", spec: .init(
