        "agents.default_subagent_reasoning_effort": .init(en: "Default reasoning effort for spawned agents. An explicit spawn effort takes precedence.", es: "Esfuerzo de razonamiento por defecto de los agentes generados. Un esfuerzo explícito al generarlos tiene prioridad.", spec: .init(
