        "agents.enabled": .init(en: "Enable or disable multi-agent tools (default: true).", es: "Activa o desactiva las herramientas multiagente (por defecto: true).", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "agents", deprecated: false, min: nil, max: nil)),
        "agents.interrupt_message": .init(en: "Record a model-visible message when an agent turn is interrupted (default: true).", es: "Registra un mensaje visible para el modelo cuando se interrumpe el turno de un agente (por defecto: true).", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "agents", deprecated: false, min: nil, max: nil)),
        "agents.max_concurrent_threads_per_session": .init(en: "Maximum number of spawned-agent threads that can be open concurrently, excluding the primary thread. When unset, Codex chooses the default.", es: "Número máximo de hilos de agentes generados que pueden estar abiertos a la vez, sin contar el hilo principal. Si no se define, Codex elige el valor por defecto.", spec: .init(
