            kind: .number, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "agents", deprecated: true, min: nil, max: nil)),
        "allow_login_shell": .init(en: "Allow shell-based tools to use login-shell semantics. Defaults to `true`; when `false`, `login = true` requests are rejected and omitted `login` defaults to non-login shells.", es: "Permite que las herramientas de shell usen semántica de login shell. Por defecto es `true`; si es `false`, se rechazan las solicitudes con `login = true` y, si se omite `login`, se usan shells sin login.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: "true", scopes: [.user, .project], topic: "General", deprecated: false, min: nil, max: nil)),
        "allow_symlinked_codex_home": .init(en: "On macOS, allow writable sandbox roots at or under `$CODEX_HOME` to follow symlinks. Codex reads this only from the execution host's `$CODEX_HOME/config.toml` at startup. Enabling it trusts targets outside that directory and targets that change between commands. It grants no additional writable roots. Defaults to `false`.", es: "En macOS, permite que las raíces escribibles del sandbox en `$CODEX_HOME` o debajo de él sigan enlaces simbólicos. Codex lo lee solo del `$CODEX_HOME/config.toml` del host de ejecución al iniciar. Activarlo confía en destinos fuera de ese directorio y en destinos que cambian entre comandos. No concede raíces escribibles adicionales. Por defecto es `false`.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: "false", scopes: [.user, .project], topic: "General", deprecated: false, min: nil, max: nil)),
        "analytics.enabled": .init(en: "Enable or disable analytics for this machine or profile. Setting this to `false` disables the built-in Statsig metrics exporter. Explicit OTLP metrics exporters remain active. When unset, the client default applies.", es: "Activa o desactiva la analítica en esta máquina o perfil. Con `false` se desactiva el exportador de métricas Statsig integrado. Los exportadores de métricas OTLP explícitos siguen activos. Si no se define, aplica el valor por defecto del cliente.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "analytics", deprecated: false, min: nil, max: nil)),
        "approval_policy": .init(en: "Controls when Codex pauses for approval before executing commands. You can also use `approval_policy = { granular = { ... } }` to allow or auto-reject specific prompt categories while keeping other prompts interactive. `untrusted` is unsupported, and `on-failure` is deprecated; use `on-request` for interactive runs or `never` for non-interactive runs.", es: "Controla cuándo Codex pide aprobación antes de ejecutar comandos. También puedes usar `approval_policy = { granular = { ... } }` para permitir o rechazar automáticamente categorías específicas de avisos y mantener interactivos los demás. `untrusted` no es compatible y `on-failure` está obsoleto; usa `on-request` en ejecuciones interactivas o `never` en las no interactivas.", spec: .init(
            kind: .string, options: ["on-request", "never"], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "General", deprecated: false, min: nil, max: nil)),
        "approval_policy.granular.mcp_elicitations": .init(en: "When `true`, MCP elicitation prompts are allowed to surface instead of being auto-rejected.", es: "Si es `true`, se permite mostrar los avisos de elicitación de MCP en lugar de rechazarlos automáticamente.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "approval_policy", deprecated: false, min: nil, max: nil)),
        "approval_policy.granular.request_permissions": .init(en: "When `true`, prompts from the `request_permissions` tool are allowed to surface.", es: "Si es `true`, se permite mostrar los avisos de la herramienta `request_permissions`.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "approval_policy", deprecated: false, min: nil, max: nil)),
        "approval_policy.granular.rules": .init(en: "When `true`, approvals triggered by execpolicy `prompt` rules are allowed to surface.", es: "Si es `true`, se permite mostrar las aprobaciones provocadas por reglas `prompt` de execpolicy.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "approval_policy", deprecated: false, min: nil, max: nil)),
        "approval_policy.granular.sandbox_approval": .init(en: "When `true`, sandbox escalation approval prompts are allowed to surface.", es: "Si es `true`, se permite mostrar los avisos de aprobación para escalar fuera del sandbox.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "approval_policy", deprecated: false, min: nil, max: nil)),
