        "features.network_proxy.dangerously_allow_non_loopback_proxy": .init(en: "Permit non-loopback listener addresses. Defaults to `false`; enabling it can expose proxy listeners beyond localhost.", es: "Permite direcciones de escucha que no son loopback. Por defecto es `false`; habilitarlo puede exponer los listeners del proxy más allá de localhost.", spec: .init(
