        "features.network_proxy.domains": .init(en: "Domain policy for sandboxed networking. Unset by default, which means no external destinations are allowed until you add `allow` rules. Supports exact hosts, `*.example.com` for subdomains only, `**.example.com` for apex plus subdomains, and global `*` allow rules. Prefer scoped rules because `*` broadly opens public outbound access. Add `deny` rules for blocked destinations; `deny` wins on conflicts.", es: "Política de dominios para la red en sandbox. Sin definir por defecto, lo que significa que no se permite ningún destino externo hasta que agregues reglas `allow`. Admite hosts exactos, `*.example.com` solo para subdominios, `**.example.com` para el dominio raíz más subdominios y reglas `allow` globales con `*`. Prefiere reglas acotadas, porque `*` abre ampliamente el acceso saliente público. Agrega reglas `deny` para destinos bloqueados; `deny` prevalece en los conflictos.", spec: .init(
            kind: .object, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.network_proxy.enable_socks5": .init(en: "Expose SOCKS5 support. Defaults to `true`.", es: "Expone compatibilidad con SOCKS5. Por defecto es `true`.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: "true", scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.network_proxy.enable_socks5_udp": .init(en: "Allow UDP over SOCKS5. Defaults to `true`.", es: "Permite UDP sobre SOCKS5. Por defecto es `true`.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: "true", scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.network_proxy.enabled": .init(en: "Start the sandboxed-command network proxy when command network access is enabled. Defaults to `false`; permission-profile domain rules are not enforced while the proxy is off.", es: "Inicia el proxy de red de comandos en sandbox cuando el acceso a la red de comandos está habilitado. Por defecto es `false`; las reglas de dominio de los perfiles de permisos no se aplican mientras el proxy está apagado.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: "false", scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.network_proxy.unix_sockets": .init(en: "Unix socket policy for sandboxed networking. Unset by default; add `allow` entries for permitted sockets.", es: "Política de sockets Unix para la red en sandbox. Sin definir por defecto; agrega entradas `allow` para los sockets permitidos.", spec: .init(
            kind: .object, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.personality": .init(en: "Removed feature flag. Accepted for compatibility and ignored.", es: "Indicador de función eliminado. Se acepta por compatibilidad y se ignora.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.prefer_mxc": .init(en: "Prefer MXC for local Windows execution when native capabilities and policy allow it; otherwise retain the configured legacy sandbox and setup. Disabled by default in the standalone CLI; the desktop app can enable it through rollout configuration. Command failures don't trigger fallback.", es: "Prefiere MXC para la ejecución local en Windows cuando las capacidades nativas y la política lo permitan; en caso contrario, conserva el sandbox heredado y la configuración establecidos. Desactivado por defecto en el CLI independiente; la app de escritorio puede habilitarlo mediante configuración de rollout. Los fallos de comandos no activan el respaldo.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.prevent_idle_sleep": .init(en: "Prevent the machine from sleeping while a turn is actively running (experimental; off by default).", es: "Evita que el equipo se suspenda mientras un turno se está ejecutando (experimental; desactivado por defecto).", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.remote_plugin": .init(en: "Enable the remote plugin catalog (stable; on by default).", es: "Habilita el catálogo de plugins remotos (estable; activado por defecto).", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.rollout_budget.enabled": .init(en: "Enable rollout budget tracking. This feature is under development and off by default. When enabled, set both `limit_tokens` and `reminder_at_remaining_tokens`.", es: "Habilita el seguimiento del presupuesto de rollout. Esta función está en desarrollo y desactivada por defecto. Al habilitarla, define tanto `limit_tokens` como `reminder_at_remaining_tokens`.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.rollout_budget.limit_tokens": .init(en: "Positive token limit for rollout budget tracking. Required when rollout budget is enabled.", es: "Límite positivo de tokens para el seguimiento del presupuesto de rollout. Obligatorio cuando el presupuesto de rollout está habilitado.", spec: .init(
            kind: .integer, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.rollout_budget.prefill_token_weight": .init(en: "Finite non-negative multiplier for prefill tokens in rollout budget accounting. Defaults to `1.0`.", es: "Multiplicador finito no negativo para los tokens de prefill en el cálculo del presupuesto de rollout. Por defecto es `1.0`.", spec: .init(
            kind: .number, options: [], allowsCustom: true, defaultJSON: "1.0", scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.rollout_budget.reminder_at_remaining_tokens": .init(en: "Send a reminder as the remaining weighted token budget crosses each threshold. Supply the list when rollout budget tracking is enabled. Each value must be positive and below `limit_tokens`.", es: "Envía un recordatorio cuando el presupuesto ponderado de tokens restantes cruza cada umbral. Indica la lista al habilitar el seguimiento del presupuesto de rollout. Cada valor debe ser positivo y menor que `limit_tokens`.", spec: .init(
