        "features.rollout_budget.sampling_token_weight": .init(en: "Finite non-negative multiplier for sampled tokens in rollout budget accounting. Defaults to `1.0`.", es: "Multiplicador finito no negativo para los tokens muestreados en el cálculo del presupuesto de rollout. Por defecto es `1.0`.", spec: .init(
            kind: .number, options: [], allowsCustom: true, defaultJSON: "1.0", scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.shell_snapshot": .init(en: "Snapshot shell environment to speed up repeated commands (stable; on by default).", es: "Guarda una instantánea del entorno del shell para acelerar comandos repetidos (estable; activado por defecto).", spec: .init(
