        "features.skill_mcp_dependency_install": .init(en: "Allow prompting and installing missing MCP dependencies for skills (stable; on by default).", es: "Permite solicitar e instalar las dependencias MCP faltantes de los skills (estable; activado por defecto).", spec: .init(
