        "features.unified_exec": .init(en: "Use resumable command execution (stable; enabled on all platforms). User opt-outs are ignored. Managed requirements can disable resumable processes and `write_stdin`, leaving one-shot `exec_command` available.", es: "Usa ejecución de comandos reanudable (estable; habilitada en todas las plataformas). Se ignoran las desactivaciones del usuario. Los requisitos administrados pueden deshabilitar los procesos reanudables y `write_stdin`, dejando disponible `exec_command` de una sola ejecución.", spec: .init(
            kind: .bool, options: [], allowsCustom: true, defaultJSON: nil, scopes: [.user, .project], topic: "features", deprecated: false, min: nil, max: nil)),
        "features.view_image": .init(en: "Enable the built-in `view_image` tool for opening local images. Defaults to `true`.", es: "Habilita la herramienta integrada `view_image` para abrir imágenes locales. Por defecto es `true`.", spec: .init(
