            kind: .string, options: ["auto", "prompt", "writes", "approve"], allowsCustom: false, defaultJSON: nil, scopes: [.user, .project], topic: "mcp_servers", deprecated: false, min: nil, max: nil)),
        "mcp_servers.<id>.disabled_tools": .init(en: "Deny list applied after `enabled_tools` for the MCP server.", es: "Lista de denegadas que se aplica después de `enabled_tools` para el servidor MCP.", spec: .init(
