        "memories.generate_memories": .init(en: "When `false`, newly created threads are not stored as memory-generation inputs. Defaults to `true`.", es: "Si es `false`, los hilos recién creados no se guardan como entradas para generar memorias. Por defecto es `true`.", spec: .init(
